    });
    const { fields } = useFieldArray({
      control,
      name: 'test',
    });

    return (
      <form>
        <ul>
          {fields.map((item, index) => {
            return (
              <li key={item.id}>
                <input
                  {...register(`test.${index}.firstName`, { required: true })}
                />
                <Controller
                  render={({ field }) => <input {...field} />}
                  name={`test.${index}.lastName`}
                  control={control}
                />
              </li>
            );
